"""Original power papers spanning generation, transmission and distribution."""
import math
from prediction_content import item as Q, number as N, choose

def paper(r):
    out=[]
    def add(label,cases): out.append((label,choose(r,cases)))
    add('1',[
      Q('水力発電','水力発電で用いるペルトン水車の特徴として適切なものはどれか。','高落差・比較的小流量に適する衝動水車である。',['低落差・大流量専用の反動水車である。','吸出し管内の負圧だけで回転力を得る。','水ではなく蒸気を作動流体とする。','羽根車が常に全周で水に満たされることが必須である。'],'ペルトン水車はノズルから噴出する高速ジェットをバケットで受ける衝動水車。高い落差のエネルギーを速度へ変換して利用する。'),
      Q('水力発電','水車のキャビテーションに関する説明として適切なものはどれか。','局所的な圧力低下で生じた気泡の崩壊が、壊食や振動の原因となる。',['水圧が高いほど必ず発生しやすい電気現象である。','水中の酸素がすべて化学的に燃焼する現象である。','発生すると必ず水車効率が改善する。','発電機の励磁電流だけを増加すれば常に解消する。'],'水の圧力が飽和蒸気圧以下となると気泡が生じ、その後高圧部で崩壊する。吸出し高さなど水力設計上の条件が重要。'),
      Q('水力発電','河川流量が少なくなったときも一定の発電を続けやすくする設備構成として、最も適切なものはどれか。','貯水池に水を蓄え、流入量と使用水量の時間差を調整する。',['常に流入水をすべて直ちに使い切る。','貯水池を空に保つことを唯一の運転条件とする。','発電機の極数を毎時間変更する。','送電線の抵抗を増やして水量を補う。'],'貯水池式は水を時間的に貯留し、出水時と渇水時や需要の変動に合わせて発電使用水量を調整できる。エネルギーそのものを無から作るわけではない。')])
    add('2',[
      Q('火力発電','再熱サイクルを採用する蒸気タービン発電の説明として適切なものはどれか。','一度膨張した蒸気を再加熱して、後段のタービンで膨張させる。',['排気をすべて空気中へ捨てることを再熱という。','復水器の冷却水だけを電気ヒータで加熱する。','発電機の銅損だけを熱源として使う。','タービンを停止したまま蒸気圧を下げる。'],'高圧タービンで膨張させた蒸気を再熱器へ戻し、再びタービンへ送る。後段の湿りを抑え、効率の改善にも寄与する。'),
      Q('火力発電','コンバインドサイクル発電の基本構成として適切なものはどれか。','ガスタービンの排熱を利用して蒸気を作り、蒸気タービンでも発電する。',['水車を2台直列につなぎ、河川水だけを利用する。','蒸気タービンの電流を整流して太陽電池へ戻す。','原子炉内で風力タービンを回転させる。','ガスタービンの排熱を使わずすべて冷却して捨てる。'],'ガスタービンの高温排ガスを排熱回収ボイラで利用し、蒸気タービンも駆動する。単独のガスタービンより燃料の熱を有効利用できる。'),
      Q('火力発電','ボイラの空気予熱器の主な目的はどれか。','排ガスの熱で燃焼用空気を予熱して、熱損失を減らす。',['発電機の周波数を直接変換する。','蒸気中の水滴だけを遠心分離する。','冷却塔内の水を凍結させる。','排ガス中の熱を必ずすべて大気へ捨てる。'],'空気予熱器は排ガスから燃焼用空気へ熱を回収する。給水を予熱する節炭器と、加熱される対象を区別する。')])
    add('3',[
      Q('原子力発電','軽水炉における減速材の役割として適切なものはどれか。','核分裂で生じる速い中性子を減速する。',['発電機の回転速度を機械的に減らす。','放射性物質を必ず非放射性に変換する。','核分裂を起こすためにすべての中性子を吸収する。','交流を直流へ変換する。'],'軽水炉では水が中性子を減速し、熱中性子による核分裂を起こしやすくする。制御棒の中性子吸収作用とは役割が異なる。'),
      Q('原子力発電','加圧水型原子炉（PWR）の基本構成として正しいものはどれか。','一次冷却水を高圧に保ち、蒸気発生器を介して二次側に熱を渡す。',['炉内で発生した蒸気を必ず直接タービンへ送る。','一次冷却材として空気のみを使用する。','蒸気発生器を設けると原子炉が不要になる。','制御棒の代わりに発電機のブラシだけで反応を制御する。'],'PWRでは一次系と二次系を蒸気発生器で分離する。炉内で沸騰させた蒸気をタービンへ送るBWRとの違いを押さえる。'),
      Q('原子力発電','原子炉の制御棒に用いる材料に求められる主な性質はどれか。','中性子をよく吸収する性質。',['可視光だけを反射する性質。','電気抵抗が完全に0になる性質。','高速回転時に磁束を発生する性質。','中性子を必ず増殖し続ける性質。'],'制御棒は中性子を吸収して核分裂の連鎖反応を調整する。ホウ素やカドミウムなど、中性子吸収能力のある材料を利用する。')])
    add('4',[
      Q('蓄電・新エネルギー','太陽光発電用パワーコンディショナのMPPT制御の目的として適切なものはどれか。','日射や温度に応じて、太陽電池の出力電力が最大となる動作点を追従する。',['電流を常に0Aに固定する。','太陽電池の端子を常時短絡する。','日射量そのものを電気的に増加させる。','交流側の周波数を日射量と同じ数値にする。'],'太陽電池の電圧電流特性は条件により変わる。MPPTは電圧と電流の積が最大となる点を探索・追従する。'),
      Q('蓄電・新エネルギー','風力発電の出力変動を系統へ与える影響の緩和策として適切なものはどれか。','蓄電池を充放電させて短時間の出力変動を緩和する。',['風速と無関係に必ず定格出力を発生させる。','蓄電池を接続すればエネルギー損失が必ず0になる。','配電線の絶縁をなくして電流を逃がす。','発電機を短絡したまま通常運転する。'],'変動時に充放電を制御して平滑化できる。ただし蓄電池の容量・出力と充電率の制約があり、任意の長時間の変動を無制限には補えない。'),
      Q('蓄電・新エネルギー','燃料電池発電の基本原理として適切なものはどれか。','燃料と酸化剤の電気化学反応から直接電力を取り出す。',['燃料を燃やして必ず蒸気タービンだけを回す。','外部から電力を受けずに同じ燃料を永久に再生する。','永久磁石の磁束だけを消費して発電する。','核融合反応による質量欠損だけを利用する。'],'燃料電池は電気化学反応によって化学エネルギーを電気へ変換する。燃料の供給が必要で、二次電池の充放電と同じ意味ではない。')])
    add('5',[
      Q('変電設備','負荷時タップ切換変圧器の主な目的として適切なものはどれか。','負荷に給電しながら巻数比を調整し、電圧を調整する。',['通常運転時の周波数を巻数比だけで変更する。','三相交流を必ず直流に変える。','鉄損と銅損を完全に0にする。','保護接地を不要にする。'],'タップで有効巻数を切り換えると巻数比が変わり、二次電圧を調整できる。交流周波数は変圧器の巻数比では変わらない。'),
      Q('変電設備','変圧器のブッフホルツ継電器が主に検出するものはどれか。','油入変圧器内部の異常によるガス発生や急激な油流。',['送電線の通常の風圧。','太陽電池の最大電力点。','負荷側の照度。','電力計の積算値だけ。'],'コンサベータを備えた油入変圧器などで、内部故障に伴うガスや油の動きを利用して警報・遮断を行う保護装置である。'),
      Q('変電設備','同じ仕様の変圧器を並列運転するとき、循環電流を抑えるための条件として適切なものはどれか。','極性・変圧比・位相変位などを整合させる。',['二次定格電圧を意図的に大きく違わせる。','一次側と二次側の周波数を別々に設定する。','一方だけを逆極性で接続する。','保護装置をすべて外せばよい。'],'二次側起電力が不一致だと負荷へ供給しない循環電流が流れる。極性、変圧比、位相変位、短絡インピーダンスなどの条件を確認する。')])
    add('6',[
      Q('配電・保護','短絡事故に伴う大電流を実際に遮断する機器として適切なものはどれか。','定格遮断容量を満たす遮断器。',['負荷電流遮断能力をもたない断路器。','避雷針だけ。','指示電圧計だけ。','接地用の銅板だけ。'],'遮断器は故障電流を遮断できる。断路器は通常、電流が遮断された後に電路を目視上分離するための機器であり、役割が異なる。'),
      Q('配電・保護','配電線の過電流保護で、事故点に近い保護装置が先に動作するよう時限を協調させる主目的はどれか。','停電する範囲をできるだけ限定する。',['事故電流を必ず0になるまで増大させる。','健全な全回線も必ず同時に停止する。','保護継電器の電源を不要にする。','電線の許容温度を無限に高くする。'],'選択遮断によって事故区間を先に切り離し、上位の保護装置を後備保護として動作させる。健全回線の供給継続に役立つ。'),
      Q('配電・保護','避雷器の働きとして最も適切なものはどれか。','異常な過電圧を制限し、機器の絶縁を保護する。',['正常時の有効電力を必ず増やす。','系統の負荷電流を常時すべて大地へ流す。','短絡事故の全電流を遮断器なしで必ず遮断する。','交流の周波数を一定の比率で増加する。'],'避雷器はサージに対して動作し、過電圧を抑制する。保護する機器との絶縁協調が必要であり、遮断器の代用品ではない。')])
    add('7',[
      Q('送電線路','架空送電線で複導体を用いる効果として適切なものはどれか。','等価的な導体半径が大きくなり、表面電界が緩和される。',['線路の電気抵抗が必ず無限大になる。','コロナ開始電圧が必ず0Vになる。','送電容量が常に0になる。','導体どうしのスペーサが必ず不要になる。'],'複導体は表面電界を緩和してコロナを抑制し、線路リアクタンスなどにも影響する。導体相互の間隔を保つ設備が必要。'),
      Q('送電線路','架空送電線のコロナ損を小さくする対策として、最も適切なものはどれか。','導体の等価半径を大きくして表面電界を下げる。',['導体表面に鋭い突起を増やす。','同じ線間距離で送電電圧を際限なく上げる。','導体の直径をできるだけ小さくする。','相間の絶縁距離を0にする。'],'コロナは導体周囲の局所的な強電界により生じる。導体半径や複導体の採用、表面状態の改善などによる電界緩和が対策となる。'),
      Q('送電線路','送電電圧を2倍にし、同じ有効電力を同じ力率で送る。線路抵抗を一定とすると、抵抗損は元の何倍か。','1/4倍。',['1/2倍。','1倍。','2倍。','4倍。'],'電力一定なら線電流は電圧に反比例して1/2。抵抗損はI²Rに比例するので1/4になる。')])
    add('8',[
      Q('送電線路','交流用電力ケーブルの誘電損について、その他の条件を一定として正しい関係はどれか。','印加電圧の2乗に比例する。',['印加電圧に反比例する。','周波数に全く依存しない。','誘電正接が大きいほど必ず小さくなる。','導体の直流抵抗だけで決まる。'],'誘電損はおおむねωCV²tanδ。容量、周波数、誘電正接が一定なら電圧の2乗に比例する。'),
      Q('送電線路','地中送電ケーブルにクロスボンド接地を採用する主な目的はどれか。','金属シースの誘導電圧を相互に打ち消し、シース循環電流による損失を減らす。',['主絶縁体を短絡して使用電圧を0にする。','導体の直流抵抗を必ず0にする。','線路の周波数を3倍にする。','ケーブルを無条件に無接地にする。'],'シースを区間ごとに交差接続し、三相による誘導電圧の合計を小さくする。区間構成や接地設計などの条件が必要。'),
      Q('電気材料','CVケーブルの絶縁体として用いる材料はどれか。','架橋ポリエチレン。',['裸銅線だけ。','水銀。','黒鉛だけ。','硫酸水溶液。'],'CVは架橋ポリエチレン絶縁ビニルシースケーブル。架橋による網目状構造によって耐熱変形性などを高めている。')])
    add('9',[
      Q('配電・保護','非接地の三相系統で1相が完全地絡した。事故前の各相対地電圧が等しいとき、健全相の対地電圧の大きさは事故前のおおむね何倍になるか。','√3倍。',['0倍。','1/√3倍。','1倍。','3倍。'],'地絡相が大地電位になるので、健全相の対地電圧は線間電圧に相当する。事故前の相電圧の√3倍となる。'),
      Q('配電・保護','直接接地方式の系統を非接地方式と比較した一般的な特徴として適切なものはどれか。','地絡電流が大きくなりやすく、保護装置で検出しやすい。',['地絡電流が必ず完全に0になる。','中性点の接地によって電線の抵抗が消える。','健全相の対地電圧が必ず無限大になる。','地絡保護継電器が一切不要になる。'],'直接接地は地絡時の大きな故障電流を前提に保護する。非接地に比べ健全相の対地過電圧を抑えやすい一方、大電流への対策が必要。'),
      Q('配電・保護','非接地系統の地絡電流について、対地静電容量以外の条件が同じとき、一般に正しいものはどれか。','線路が長くなり対地静電容量が増えると、地絡電流も大きくなる。',['線路長によらず必ず0Aとなる。','対地静電容量が増えるほど必ず小さくなる。','地絡相だけの導体抵抗で決まり、周波数は関係しない。','直流電源の内部抵抗だけで決まる。'],'非接地系統の地絡電流には、健全相の対地静電容量を通る充電電流が関係する。容量や周波数が大きくなると、この成分も大きくなる。')])
    add('10',[
      Q('配電・保護','単相3線式で中性線が断線し、両側の負荷が不平衡である。負荷端電圧について適切なものはどれか。','一方が上昇し、他方が低下するおそれがある。',['両側とも常に元の電圧を正確に保つ。','両側とも必ず0Vになる。','負荷抵抗が異なっても常に同じ電流にならない。','線間電圧が必ず半分になる。'],'中性線が切れると、両側の負荷が線間電圧に対する直列回路となる。抵抗の大きな側に高い電圧が分担され、過電圧の危険がある。'),
      Q('配電・保護','スポットネットワーク方式の特徴として適切なものはどれか。','複数の受電回線とネットワーク変圧器で高い供給信頼度を得る。',['1回線だけで受電することが必須である。','変圧器の二次側を一切接続してはならない。','ネットワークプロテクタは通常の電力量計だけで構成する。','どのような多重事故でも停電しないことを保証する。'],'複数系統から同じ需要家へ給電し、回線単独の事故時も給電継続を図る方式。多重故障などまで無条件に無停電という意味ではない。'),
      Q('配電・保護','ループ配電線を常時は一部開放して放射状で運用する理由として適切なものはどれか。','事故時の保護協調を簡単にし、必要時に開放点を変更して融通できる。',['開放点を設けると健全部分にも必ず電圧がなくなる。','電線の絶縁を不要にする。','負荷の有効電力を消滅させる。','配電線を直流に変換する。'],'通常は放射状として保護を行い、事故区間を切り離した後に他回線側から復旧する構成がとれる。負荷容量や電圧条件の確認は必要。')])
    add('11',[
      Q('電気材料','油入変圧器の絶縁油に求められる性質として適切なものはどれか。','十分な絶縁性能と、冷却のための良好な流動性。',['高い含水率と高い導電率。','通常使用温度で必ず固体になる性質。','対流を妨げるための極端に高い粘度。','燃焼しやすさだけ。'],'絶縁油は絶縁と放熱の両方を担う。水分や劣化生成物は絶縁性能を低下させるため、状態監視や管理が重要。'),
      Q('電気材料','がいし表面に塩分が付着し、霧などで湿潤したときに起こりやすくなる現象はどれか。','表面漏れ電流の増加と、沿面フラッシオーバ。',['絶縁抵抗の無限大への上昇。','周波数の0Hzへの固定。','導体の超電導化。','すべての機械振動の消失。'],'塩分を含む水膜により表面の導電性が増す。局部アークが進展して沿面放電に至る場合があり、洗浄や汚損対策が行われる。'),
      Q('電気材料','アルミ導体鋼心線（ACSR）の鋼心の主な役割はどれか。','機械的な引張強さを補う。',['電気絶縁をすべて担う。','交流を直流へ整流する。','電線の温度を常に0℃に保つ。','導体周囲の空気を完全に真空にする。'],'外層のアルミニウムで主に電流を流し、鋼心によって機械的強度を高める。電気的特性と機械的特性の両立を図った構造。')])
    voltage,z=choose(r,[(6600,2),(3300,1),(11000,5)])
    current=voltage/(math.sqrt(3)*z)
    out.append(('12',N('変電設備',f'線間電圧{voltage}Vの対称三相電源から、1相当たりのインピーダンスの大きさ{z}Ωを介して三相短絡が生じた。電源内部インピーダンスはこの値に含まれ、事故前は無負荷である。短絡電流の実効値に最も近いものはどれか。',round(current),[round(current/3),round(current/math.sqrt(3)),round(current*math.sqrt(3)),round(current*3)],'A',f'1相分の相電圧VL/√3を相インピーダンスで割る。I={voltage}/(√3×{z})≒{current:.1f}A。')))
    p,cos=choose(r,[(80,.8),(120,.6),(60,.8)])
    qc=p*math.sqrt(1-cos*cos)/cos
    out.append(('13',N('配電計算',f'有効電力{p}kW、遅れ力率{cos:g}の三相負荷を、進相コンデンサで力率1にする。必要なコンデンサ容量は何kvarか。電圧と有効電力は一定とする。',qc,[qc/2,qc*2,p,p/cos],'kvar',f'必要な進み無効電力はQc=P tanφ=P√(1−cos²φ)/cosφ={qc:g}kvar。')))
    energy,maxload=choose(r,[(720,60),(1440,80),(960,100)])
    lf=energy/(24*maxload)*100
    out.append(('14',N('電力需給',f'ある需要家の1日の電力量が{energy}kWh、同じ日の最大需要電力が{maxload}kWだった。日負荷率は何%か。',lf,[lf/2,lf*2,lf/4,lf*1.5],'%',f'平均需要電力は{energy}/24={energy/24:g}kW。負荷率=平均/最大×100={lf:g}%。需要率とは異なる。')))
    # Paired B scenarios vary the physical question, rather than only labels.
    water=choose(r,[(40,100,.9),(25,200,.8),(50,80,.85)])
    flow,head,eff=water; output=9.8*flow*head*eff
    common=f'水力発電所の使用水量{flow}m³/s、有効落差{head}m、水車と発電機の総合効率{eff*100:g}%である。水の密度1000kg/m³、重力加速度9.8m/s²とする。'
    out += [('15a',N('水力発電',common+'(a) 発電出力は何kWか。',output,[output/2,output*2,output/eff,output*eff],'kW',f'P=ρgQHη/1000=9.8×{flow}×{head}×{eff:g}={output:g}kW。')),
            ('15b',N('水力発電',common+'(b) この状態を2時間保ったときの発電電力量は何MWhか。',output*2/1000,[output/1000,output*4/1000,output*2,output/2/1000],'MWh',f'出力{output/1000:g}MWに2時間を掛け、W={output*2/1000:g}MWh。kWとMWの換算も行う。'))]
    span,sag,weight=choose(r,[(80,2,10),(100,2.5,12),(120,3,8)])
    tension=weight*span**2/(8*sag)/1000
    extra=8*sag*sag/(3*span)
    common=f'支持点の高さが等しい架空電線で、径間S={span}m、たるみD={sag:g}m、単位長さの重量w={weight}N/mである。放物線近似を用い、風圧や着雪は無視する。'
    out += [('16a',N('送電線路',common+'(a) 水平張力T=wS²/(8D)は何kNか。',tension,[tension/2,tension*2,tension/4,tension*4],'kN',f'T={weight}×{span}²/(8×{sag:g})={tension*1000:g}N={tension:g}kN。')),
            ('16b',N('送電線路',common+'(b) 電線の長さL≒S+8D²/(3S)から求める余長L−Sに最も近いものはどれか。',round(extra,3),[round(extra/2,3),round(extra*2,3),round(extra*3,3),round(extra*4,3)],'m',f'L−S=8×{sag:g}²/(3×{span})≒{extra:.3f}m。たるみそのものと、径間を超える電線の長さは異なる。'))]
    source,ia,ib,line_r=choose(r,[(100,30,20,.1),(100,40,20,.2),(110,50,30,.1)])
    # Independent balanced 100/200 V load; resistive loads with given currents.
    common=f'単相3線式の電圧線L1-NとL2-Nの電源電圧は各{source}V。末端の抵抗負荷電流はL1側{ia}A、L2側{ib}Aである。電圧線1本の抵抗は{line_r:g}Ω、中性線抵抗は0Ωとし、他のインピーダンスを無視する。'
    loss=(ia**2+ib**2)*line_r; end=source-ia*line_r
    out += [('17a',N('配電計算',common+'(a) L1側の負荷端電圧は何Vか。',end,[source,source+ia*line_r,source-(ia+ib)*line_r,source-ib*line_r],'V',f'中性線抵抗が0なので中性点の移動はない。L1の電圧降下は{ia}×{line_r:g}={ia*line_r:g}V、端子電圧は{end:g}V。')),
            ('17b',N('配電計算',common+'(b) 2本の電圧線の合計抵抗損は何Wか。',loss,[loss/2,loss*2,(ia-ib)**2*line_r,(ia+ib)**2*line_r],'W',f'両電圧線のI²Rを加算する。P=({ia}²+{ib}²)×{line_r:g}={loss:g}W。中性線抵抗は0なのでその損失は0。'))]
    return out
